#[test]
fn generated_roof_jump_edges_have_character_sized_walkable_approaches() {
    use robin_engine::coordinates::MapPoint;
    use robin_engine::pathfinder::PathFinder;

    for bytes in [
        include_bytes!("fixtures/asset-jump-movement-blocked.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-courtyard.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-level-contours.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-complete-roofs.level.json").as_slice(),
    ] {
        let mut assets = LevelAssets::new();
        let engine = construct(bytes, &mut assets);
        let mut grid = engine.fast_grid().clone();
        let graph = &assets.navigation.pathfinder_graph;
        let mut finder = PathFinder::new();
        finder.initialize_from_graph(graph, &mut grid);
        let footprint = grid.try_move_box_half_diagonal(0).unwrap();
        assert!(!grid.level.jump_lines.is_empty());
        for line in &grid.level.jump_lines {
            let dx = line.point_b.x - line.point_a.x;
            let dy = line.point_b.y - line.point_a.y;
            let length = dx.hypot(dy);
            let sector =
                grid.level.sectors[line.sector_index.unwrap().get() as usize].sector_number;
            for t in [0.0, 0.25, 0.5, 0.75, 1.0] {
                let edge = MapPoint::new(line.point_a.x + dx * t, line.point_a.y + dy * t);
                let inside = MapPoint::new(edge.x + dy / length * 4.0, edge.y - dx / length * 4.0);
                for (start, goal) in [(inside, edge), (edge, inside)] {
                    assert!(
                        grid.is_reachable_thick(start, goal, line.layer, footprint),
                        "jump approach is too narrow for a character at {edge:?}"
                    );
                    let route = finder
                        .find_path(
                            graph, &grid, line.layer, i16::from(sector) as u16,
                            0, start, goal, false,
                        )
                        .unwrap_or_else(|| {
                            panic!(
                                "no walking approach from {start:?} to {goal:?} on layer {} sector {sector:?}",
                                line.layer
                            )
                        });
                    assert_eq!(route.last(), Some(&goal));
                    for segment in route.windows(2) {
                        assert!(
                            grid.is_reachable_thick(segment[0], segment[1], line.layer, footprint),
                            "jump approach is too narrow for a character at {edge:?}"
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn compiled_roof_jump_routes_enforce_character_skills_and_destination_helpers() {
    use robin_engine::element::{ElementKind, Posture};
    use robin_engine::gate::{ActorAuthInfo, find_path_gates_with_sector_indices};

    for bytes in [
        include_bytes!("fixtures/asset-jump-movement-blocked.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-changing-approach.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-detached.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-geometric.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-obstructed.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-courtyard.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-level-contours.level.json").as_slice(),
        include_bytes!("fixtures/asset-jump-complete-roofs.level.json").as_slice(),
    ] {
        let mut assets = LevelAssets::new();
        let engine = construct(bytes, &mut assets);
        let view = engine.presentation_view();
        let doors = view.doors();
        assert!(doors.iter().any(|door| door.is_jump()));
        for jump in doors.iter().filter(|door| door.is_jump()) {
            let actor = ActorAuthInfo {
                kind: ElementKind::ActorPc,
                pc_auth_bit: 1,
                has_lockpick: false,
                has_climb: false,
                has_jump: true,
                is_rider: false,
                posture: Posture::Upright,
            };
            for direct in [false, true] {
                let (
                    start,
                    goal,
                    source_sector,
                    goal_sector,
                    source_index,
                    goal_index,
                    needs_helper,
                ) = if direct {
                    (
                        jump.point_out,
                        jump.point_in,
                        jump.sector_out,
                        jump.sector_in,
                        jump.sector_out_index,
                        jump.sector_in_index,
                        jump.jump_line_in_helper_needed,
                    )
                } else {
                    (
                        jump.point_in,
                        jump.point_out,
                        jump.sector_in,
                        jump.sector_out,
                        jump.sector_in_index,
                        jump.sector_out_index,
                        jump.jump_line_out_helper_needed,
                    )
                };
                let route = |actor: &ActorAuthInfo| {
                    find_path_gates_with_sector_indices(
                        std::slice::from_ref(jump),
                        (start.x, start.y),
                        i16::from(source_sector) as u16,
                        source_index,
                        (goal.x, goal.y),
                        i16::from(goal_sector) as u16,
                        goal_index,
                        Some(actor),
                        false,
                        &|_| true,
                        &|_| None,
                    )
                };
                assert_eq!(route(&actor).is_some(), !needs_helper);
                let supported = ActorAuthInfo {
                    posture: Posture::OnShoulders,
                    ..actor
                };
                let path =
                    route(&supported).expect("a supported jumper can cross the compiled roof pair");
                assert_eq!(path.len(), 1);
                assert_eq!(path[0].direct, direct);
                assert!(
                    route(&ActorAuthInfo {
                        has_jump: false,
                        ..supported
                    })
                    .is_none()
                );
                assert!(
                    route(&ActorAuthInfo {
                        kind: ElementKind::ActorSoldier,
                        ..supported
                    })
                    .is_none()
                );
            }
        }
    }
}

