#[test]
fn compiled_door_retains_alternate_lock_rules() {
    let mut descriptor: serde_json::Value =
        serde_json::from_slice(include_bytes!("fixtures/asset-compiled.level.json")).unwrap();
    let door = &mut descriptor["asset_geometry"]["doors"][0];
    door["door_type"] = 7.into();
    door["locked_pc_after_patch"] = true.into();
    door["unlockable_after_patch"] = true.into();
    door["locked_npc_villain_after_patch"] = true.into();
    door["locked_npc_civilian_after_patch"] = true.into();
    let mut assets = LevelAssets::new();
    let engine = construct(&serde_json::to_vec(&descriptor).unwrap(), &mut assets);
    let mut door = engine.presentation_view().doors()[0].clone();
    assert_eq!(door.door_type, robin_engine::gate::DoorType::Trap);
    assert!(!door.locked_pc);
    door.swap_rights_patch();
    assert!(
        door.locked_pc && door.unlockable && door.locked_npc_villain && door.locked_npc_civilian
    );
    door.swap_rights_patch();
    assert!(
        !door.locked_pc
            && !door.unlockable
            && !door.locked_npc_villain
            && !door.locked_npc_civilian
    );
}

#[test]
fn sloped_asset_surface_constructs_elevation_and_navigation_holes() {
    let mut assets = LevelAssets::new();
    let engine = construct(
        include_bytes!("fixtures/asset-sloped.level.json"),
        &mut assets,
    );
    let surface = assets.environment.static_sight_obstacles.last().unwrap();
    assert!((surface.compute_top_z(320., 320.) - 10.).abs() < 0.001);
    assert!((surface.compute_top_z_from_projection(320., 310.) - 10.).abs() < 0.001);
    assert!((surface.compute_top_z_from_projection(400., 300.) - 50.).abs() < 0.001);
    use robin_engine::coordinates::MapPoint;
    let grid = engine.fast_grid();
    assert!(grid.is_reachable_thin(MapPoint::new(310., 315.), MapPoint::new(350., 295.), 0));
    // Cross the authored hole, away from the solid obstacle.
    assert!(!grid.is_reachable_thin(MapPoint::new(365., 337.5), MapPoint::new(385., 327.5), 0));
    // Cross the collision volume where it intersects the ramp.
    assert!(!grid.is_reachable_thin(MapPoint::new(330., 330.), MapPoint::new(360., 315.), 0));
}

#[test]
fn disconnected_lift_preserves_collision_and_independent_traversal() {
    use robin_engine::coordinates::{MapPoint, WorldPoint3D};
    use robin_engine::sight_obstacle::{ObstacleList, SIGHTOBSTACLE_SOLID, is_reachable_impact_3d};
    let mut assets = LevelAssets::new();
    let engine = construct(
        include_bytes!("fixtures/asset-disconnected-lift.level.json"),
        &mut assets,
    );
    let grid = engine.fast_grid();
    assert!(!grid.is_reachable_thin(MapPoint::new(330., 345.), MapPoint::new(370., 345.), 0));
    assert!(grid.is_reachable_thin(MapPoint::new(310., 320.), MapPoint::new(380., 320.), 0));
    assert!(
        is_reachable_impact_3d(
            WorldPoint3D::new(345., 345., 100.),
            WorldPoint3D::new(345., 345., 1.),
            SIGHTOBSTACLE_SOLID,
            ObstacleList::from_slice_all_active(&assets.environment.static_sight_obstacles),
            None,
            None,
        )
        .is_some()
    );
    let lifts: Vec<_> = grid
        .level
        .sectors
        .iter()
        .filter(|sector| sector.sector_type.is_lift())
        .collect();
    assert_eq!(lifts.len(), 1);
    assert_eq!(lifts[0].gate_indices.len(), 2);
}

