#[test]
fn terrain_bound_entrances_remain_approachable_and_link_the_building() {
    use robin_engine::coordinates::MapPoint;
    use robin_engine::gate::{DoorIndex, find_path_into_door_with_sector_index};
    use robin_engine::pathfinder::PathFinder;
    let mut assets = LevelAssets::new();
    let engine = construct(
        include_bytes!("fixtures/asset-terrain-interior.level.json"),
        &mut assets,
    );
    let graph = &assets.navigation.pathfinder_graph;
    let mut grid = engine.fast_grid().clone();
    let mut finder = PathFinder::new();
    finder.initialize_from_graph(graph, &mut grid);
    let view = engine.presentation_view();
    let doors = view.doors();
    assert_eq!(doors.len(), 2);
    assert_eq!(doors[0].sector_in, doors[1].sector_in);
    for (index, door) in doors.iter().enumerate() {
        let start = MapPoint::new(door.point_out.x, door.point_out.y - 20.);
        for (start, end) in [(start, door.point_out), (door.point_out, start)] {
            let path = finder
                .find_path(
                    graph,
                    &grid,
                    door.layer_out,
                    i16::from(door.sector_out) as u16,
                    0,
                    start,
                    end,
                    false,
                )
                .expect("terrain approach has a walkable route");
            assert_eq!(path.last(), Some(&end));
            for points in path.windows(2) {
                assert!(grid.is_reachable_thick(
                    points[0],
                    points[1],
                    door.layer_out,
                    grid.try_move_box_half_diagonal(0).unwrap()
                ));
            }
        }
        let path = find_path_into_door_with_sector_index(
            doors,
            (start.x, start.y),
            i16::from(door.sector_out) as u16,
            door.sector_out_index,
            DoorIndex::new(index as u32).unwrap(),
            None,
            false,
            &|_| true,
            &|_| None,
        );
        let path = path.expect("entrance geometry is linked into the gate graph");
        assert_eq!(
            path.last().unwrap().door_index,
            DoorIndex::new(index as u32).unwrap()
        );
        assert_eq!(door.locked_pc, index == 1);
    }
}

#[test]
fn compiled_interior_connections_follow_independent_asset_placement() {
    for (bytes, expected_rooms, expected_entrances) in [
        (
            include_bytes!("fixtures/asset-interior-editor-linked.level.json").as_slice(),
            1,
            3,
        ),
        (
            include_bytes!("fixtures/asset-interior-joined.level.json").as_slice(),
            1,
            2,
        ),
        (
            include_bytes!("fixtures/asset-interior-separated.level.json").as_slice(),
            2,
            1,
        ),
    ] {
        let mut assets = LevelAssets::new();
        let engine = construct(bytes, &mut assets);
        let grid = engine.fast_grid();
        let buildings: Vec<_> = grid
            .level
            .sectors
            .iter()
            .filter(|sector| sector.sector_type.is_building())
            .collect();
        assert_eq!(buildings.len(), expected_rooms);
        for building in buildings {
            assert_eq!(building.gate_indices.len(), expected_entrances);
        }
        assert_eq!(
            grid.level.door_projection_infos.len(),
            expected_rooms * expected_entrances
        );
    }
}

#[test]
fn terrain_bound_passage_connects_both_approaches_and_retains_lock_rules() {
    use robin_engine::coordinates::MapPoint;
    use robin_engine::gate::{DoorIndex, find_path_into_door_with_sector_index};
    let mut assets = LevelAssets::new();
    let engine = construct(
        include_bytes!("fixtures/asset-terrain-passage.level.json"),
        &mut assets,
    );
    let view = engine.presentation_view();
    let doors = view.doors();
    assert_eq!(doors.len(), 1);
    let door = &doors[0];
    assert_eq!(door.point_out, MapPoint::new(380., 348.));
    assert_eq!(door.point_in, MapPoint::new(420., 344.));
    assert!(door.locked_pc);
    assert!(!door.locked_pc_after_patch);
    assert_ne!(door.sector_in_index, door.sector_out_index);
    let grid = engine.fast_grid();
    for (point, dx, layer, sector, sector_index) in [
        (
            door.point_out,
            -20.,
            door.layer_out,
            door.sector_out,
            door.sector_out_index,
        ),
        (
            door.point_in,
            20.,
            door.layer_in,
            door.sector_in,
            door.sector_in_index,
        ),
    ] {
        let start = MapPoint::new(point.x + dx, point.y);
        assert!(grid.is_reachable_thick(
            start,
            point,
            layer,
            grid.try_move_box_half_diagonal(0).unwrap()
        ));
        assert!(grid.is_reachable_thick(
            point,
            start,
            layer,
            grid.try_move_box_half_diagonal(0).unwrap()
        ));
        let route = find_path_into_door_with_sector_index(
            doors,
            (start.x, start.y),
            i16::from(sector) as u16,
            sector_index,
            DoorIndex::new(0).unwrap(),
            None,
            false,
            &|_| true,
            &|_| None,
        )
        .expect("passage endpoint is registered in the gate graph");
        assert_eq!(route.last().unwrap().door_index, DoorIndex::new(0).unwrap());
    }
}

